<div class="grid two profile-grid"><section class="panel"><h2>Edit Information</h2><p class="muted">Update your personal and account details.</p><form method="post" enctype="multipart/form-data"><?php actionFields('profile'); ?><div class="grid two"><div><?php if($user['photo_path']): ?><img class="avatar-large" src="<?= e(url('file',['kind'=>'avatar','id'=>$user['id']])) ?>" alt="Profile photo"><?php endif;field('Change Photo','photo','','file',false,'accept="image/jpeg,image/png,image/webp"'); ?></div><div><?php field('Full Name','name',$user['name'],'text',true,'maxlength="120"'); ?><label>Position<input value="<?= e($user['role_name']) ?>" disabled></label><?php field('Email Address','email',$user['email'],'email',true,'maxlength="190"');field('Contact Number','phone',$user['phone'],'tel',false,'maxlength="40"'); ?></div></div><h3>Account Details</h3><label>Account ID<input value="<?= e($user['id']) ?>" disabled></label><?php field('Barangay','barangay',$user['barangay'],'text',true,'maxlength="120"'); ?><div class="actions"><button type="reset" class="secondary">Cancel</button><button <?= $user['must_change_password']?'disabled':'' ?>>Save Changes</button></div></form></section>
<section class="panel"><h2>Change Password</h2><p class="muted">Use at least 12 characters. Do not reuse your temporary password.</p><form method="post"><?php actionFields('password');field('Current Password','current_password','','password',true,'autocomplete="current-password"');field('New Password','new_password','','password',true,'minlength="12" maxlength="200" autocomplete="new-password"');field('Confirm New Password','confirm_password','','password',true,'minlength="12" maxlength="200" autocomplete="new-password"'); ?><div class="actions"><button type="reset" class="secondary">Cancel</button><button>Update Password</button></div></form></section></div>
